package com.example.notification.dto;
import java.time.Instant; public class NotificationResponseDto { private Long id; private String recipient; private String message; private String type; private Instant createdAt; public NotificationResponseDto(){} public NotificationResponseDto(Long id,String r,String m,String t,Instant c){this.id=id;recipient=r;message=m;type=t;createdAt=c;} public Long getId(){return id;} public void setId(Long v){id=v;} public String getRecipient(){return recipient;} public void setRecipient(String v){recipient=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getType(){return type;} public void setType(String v){type=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} }
